on conflict (id) do nothing;

update academy_settings set heatmap_display = '{"mode": "global", "fields": {"floor": true, "usage": true, "area": true, "maintenance_manwon": true, "approval_year": false, "expiry_date": false, "rooms": true, "restrooms": true, "facility_transfer": true, "has_license": true, "elevator_count": true, "parking_count": true, "road_address": true, "lot_address": true, "photos": true}}'::jsonb where id=1;
